/**
 * Re-points every issue on `sourceLabelId` at `targetLabelId`, then deletes the
 * source label. An issue that already carries the target keeps a single join
 * row: the unique (issue, label) index absorbs the duplicate. Returns how many
 * issues carried the source label before the merge.
 *
 * One transaction, so a failure leaves both labels exactly as they were.
 */
export async function mergeLabelInto(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  return getDb().transaction((tx) => {
    const sourceJoins = and(
      orgPredicate(issueLabels.orgId, orgId),
      eq(issueLabels.labelId, sourceLabelId),
    );

    const relabelled =
      tx.select({ value: count() }).from(issueLabels).where(sourceJoins).get()
        ?.value ?? 0;

    tx.insert(issueLabels)
      .select(
        tx
          .select({
            orgId: issueLabels.orgId,
            issueId: issueLabels.issueId,
            labelId: sql<LabelId>`${targetLabelId}`,
          })
          .from(issueLabels)
          .where(sourceJoins),
      )
      .onConflictDoNothing()
      .run();

    tx.delete(issueLabels).where(sourceJoins).run();
    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return relabelled;
  });
}

