/**
 * Folds `sourceLabelId` into `targetLabelId`: every issue that carried the
 * source carries the target instead, archived issues included, and the source
 * label is deleted. It removes a label just like `deleteLabel`, so it takes the
 * same archive permission.
 *
 * Both labels are resolved inside the actor's org before anything is written,
 * so a foreign or missing id changes nothing.
 */
export async function mergeLabels(
  actor: Actor,
  input: MergeLabelsInput,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:archive", orgResource(input.orgId));

  // The schema refines this too, but callers may skip the schema.
  if (input.sourceLabelId === input.targetLabelId) {
    throw new Error("Merge needs two different labels");
  }

  const source = requireFound(
    await labelRepo.findLabelById(input.orgId, input.sourceLabelId),
    "Label",
    input.sourceLabelId,
  );
  const target = requireFound(
    await labelRepo.findLabelById(input.orgId, input.targetLabelId),
    "Label",
    input.targetLabelId,
  );

  const issuesRelabelled = await labelRepo.mergeLabelInto(
    input.orgId,
    source.id,
    target.id,
  );
  return { label: target, issuesRelabelled };
}
