import { beforeAll, afterAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { getDb, issueLabels, labels } from "@/server/db";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as labelService from "@/server/services/label-service";
import { mergeLabelsSchema } from "@/schemas/label";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { NotFoundError } from "@/server/services/_support";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

async function setup(slug: string) {
  const t = await createTenant(slug);
  const mk = (name: string) => labelRepo.insertLabel({ orgId: t.org.id, name, color: "#000000", description: null });
  const source = await mk("defect");
  const target = await mk("bug");
  const other = await mk("other");
  const issues = [];
  for (let i = 0; i < 3; i++) {
    issues.push(await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: `i${i}` }), t.userIds.owner, i + 1));
  }
  // issue0: source only; issue1: source+target; issue2: target only; plus issue0 has other
  await labelRepo.setIssueLabels(t.org.id, issues[0].id, [source.id, other.id]);
  await labelRepo.setIssueLabels(t.org.id, issues[1].id, [source.id, target.id]);
  await labelRepo.setIssueLabels(t.org.id, issues[2].id, [target.id]);
  return { t, source, target, other, issues };
}

const joins = (orgId: string, labelId: string) =>
  getDb().select().from(issueLabels).all().filter((r) => r.orgId === orgId && r.labelId === labelId);

describe("mergeLabels", () => {
  it("relabels, dedups, deletes source", async () => {
    const { t, source, target, other, issues } = await setup("merge-a");
    const res = await labelService.mergeLabels(t.actors.admin, { orgId: t.org.id, sourceLabelId: source.id, targetLabelId: target.id });
    expect(res.issuesRelabelled).toBe(2);
    expect(res.label).toEqual(target);
    expect(joins(t.org.id, source.id)).toHaveLength(0);
    expect((await labelRepo.listLabels(t.org.id)).map((l) => l.id).sort()).toEqual([target.id, other.id].sort());
    const byIssue = await labelRepo.listLabelsForIssues(t.org.id, issues.map((i) => i.id));
    expect(byIssue[issues[0].id].map((l) => l.id).sort()).toEqual([target.id, other.id].sort());
    expect(byIssue[issues[1].id].map((l) => l.id)).toEqual([target.id]);
    expect(byIssue[issues[2].id].map((l) => l.id)).toEqual([target.id]);
    expect(joins(t.org.id, target.id)).toHaveLength(3);
  });

  it("member is denied", async () => {
    const { t, source, target } = await setup("merge-b");
    await expect(labelService.mergeLabels(t.actors.member, { orgId: t.org.id, sourceLabelId: source.id, targetLabelId: target.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(joins(t.org.id, source.id)).toHaveLength(2);
  });

  it("wrong org input is tenant error", async () => {
    const { t, source, target } = await setup("merge-c");
    const other = await createTenant("merge-c2");
    await expect(labelService.mergeLabels(t.actors.admin, { orgId: other.org.id, sourceLabelId: source.id, targetLabelId: target.id })).rejects.toBeInstanceOf(TenantScopeError);
    expect(joins(t.org.id, source.id)).toHaveLength(2);
  });

  it("foreign label id is not found and changes nothing", async () => {
    const { t, source } = await setup("merge-d");
    const o = await setup("merge-d2");
    await expect(labelService.mergeLabels(t.actors.admin, { orgId: t.org.id, sourceLabelId: source.id, targetLabelId: o.target.id })).rejects.toBeInstanceOf(NotFoundError);
    expect(joins(t.org.id, source.id)).toHaveLength(2);
    expect(joins(o.t.org.id, o.source.id)).toHaveLength(2);
    expect(await labelRepo.findLabelById(o.t.org.id, o.source.id)).not.toBeNull();
  });

  it("same id rejected directly, nothing changed", async () => {
    const { t, source } = await setup("merge-e");
    await expect(labelService.mergeLabels(t.actors.admin, { orgId: t.org.id, sourceLabelId: source.id, targetLabelId: source.id })).rejects.toThrow();
    expect(joins(t.org.id, source.id)).toHaveLength(2);
    expect(await labelRepo.findLabelById(t.org.id, source.id)).not.toBeNull();
  });

  it("schema rejects same id, accepts different", () => {
    const { t, source, target } = { t: { org: { id: "01HZZZZZZZZZZZZZZZZZZZZZZZ" } }, source: { id: "01J0000000000000000000000A" }, target: { id: "01J0000000000000000000000B" } };
    expect(mergeLabelsSchema.safeParse({ orgId: t.org.id, sourceLabelId: source.id, targetLabelId: source.id }).success).toBe(false);
    expect(mergeLabelsSchema.safeParse({ orgId: t.org.id, sourceLabelId: source.id, targetLabelId: target.id }).success).toBe(true);
  });
});
