  it("foreign label id is not found and changes nothing", async () => {
    const { t, source } = await setup("merge-d");
    const o = await setup("merge-d2");
    await expect(labelService.mergeLabels(t.actors.admin, { orgId: t.org.id, sourceLabelId: source.id, targetLabelId: o.target.id })).rejects.toBeInstanceOf(NotFoundError);
