  it("schema rejects same id, accepts different", () => {
    const { t, source, target } = { t: { org: { id: "01HZZZZZZZZZZZZZZZZZZZZZZZ" } }, source: { id: "01J0000000000000000000000A" }, target: { id: "01J0000000000000000000000B" } };
    expect(mergeLabelsSchema.safeParse({ orgId: t.org.id, sourceLabelId: source.id, targetLabelId: source.id }).success).toBe(false);
    expect(mergeLabelsSchema.safeParse({ orgId: t.org.id, sourceLabelId: source.id, targetLabelId: target.id }).success).toBe(true);
